// Bot Active Gate v2 — reads from webhook payload directly (no API call, no loop, no inbox hardcode)
const input = $input.first().json;
let conv = {};
try {
  conv = $('Turn In').first().json.body.conversation || {};
} catch (e) {
  // Web chat trigger path — no Chatwoot conversation, bot always replies
  return [{ json: Object.assign({}, input, { botCheck: { botActive: true, pauseReason: 'no_chatwoot_context', conversationId: null } }) }];
}

const meta = conv.meta || {};
const assignee = meta.assignee;
const attrs = conv.custom_attributes || {};
const now = Date.now();
const pausedUntil = attrs.bot_paused_until ? Date.parse(attrs.bot_paused_until) : 0;

let botActive = true;
let pauseReason = '';

// Chatwoot 4.16+ assigns new bot-handled conversations to the bot itself. That is not a human
// takeover — only a human (type 'user') assignee pauses the bot.
if (assignee && assignee.id && assignee.type !== 'agent_bot') {
  botActive = false;
  pauseReason = 'human_assigned:' + (assignee.name || assignee.id);
} else if (attrs.bot_active === false) {
  botActive = false;
  pauseReason = 'bot_active_flag_false';
} else if (pausedUntil > now) {
  botActive = false;
  pauseReason = 'paused_until:' + attrs.bot_paused_until;
}

if (!botActive) {
  // Stop silently. Chatwoot already has the customer message natively (no need to mirror).
  // No private note (would cause feedback loop with Auto-Pause).
  console.log('[Bot Active Gate] silent: ' + pauseReason + ' conv=' + conv.id);
  return [];
}

return [{ json: Object.assign({}, input, { botCheck: { botActive: true, pauseReason: '', conversationId: conv.id } }) }];

const hours = $input.first().json || {};
const base  = $('Bot Active Gate').first().json;      // keeps chatInput AND botCheck intact
const tz    = hours.timezone     || 'Europe/Belgrade';
const open  = hours.office_open  || '08:00';
const close = hours.office_close || '20:00';
const days  = hours.office_days  || '1-7';

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: tz, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit'
}).formatToParts(new Date());
const get = t => (parts.find(p => p.type === t) || {}).value;
const hh = parseInt(get('hour'), 10), mm = parseInt(get('minute'), 10);
const nowMin = hh * 60 + mm;
const isoDay = { Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6, Sun:7 }[get('weekday')] || 1;

const toMin = s => { const [a, b] = String(s).split(':').map(Number); return a * 60 + (b || 0); };
const openMin = toMin(open), closeMin = toMin(close);
const [d1, d2] = days.split('-').map(Number);
const dayOk = d2 ? (isoDay >= d1 && isoDay <= d2) : isoDay === d1;
// closeMin <= openMin means the window crosses midnight (e.g. 22:00-06:00)
const inWindow = closeMin > openMin
  ? (nowMin >= openMin && nowMin < closeMin)
  : (nowMin >= openMin || nowMin < closeMin);
const isOpen = dayOk && inWindow;
const nowLocal = String(get('hour')).padStart(2,'0') + ':' + String(get('minute')).padStart(2,'0');

return [{ json: Object.assign({}, base, {
  isOpen, nowLocal, officeOpen: open, officeClose: close,
  hoursLine: isOpen
    ? ('It is ' + nowLocal + ' local time and the team IS available now (' + open + '-' + close + ').')
    : ('It is ' + nowLocal + ' local time and the team is NOT available now. They are back at ' + open + ' local time.')
}) }];

// Tells the agent whether this guest is new, mid-conversation, or returning — and when they
// last wrote. Passes the incoming item through untouched: Has Audio? / Has Image? and the agent
// all read fields from it.
const base = $('Compute Open State').first().json;
const row  = $input.first().json || {};
const tz   = ($('Fetch Office Hours').isExecuted && $('Fetch Office Hours').first().json.timezone) || 'Europe/Belgrade';

const prior       = Number(row.prior_msgs || 0);
const lastSeen    = row.last_seen ? new Date(row.last_seen) : null;
const lastByStaff = /^\[Reply from our staff/.test(String(row.last_content || ''));

let note = '';
if (row.error || row.prior_msgs === undefined) {
  note = '';                                   // lookup failed: say nothing rather than guess
} else if (prior === 0) {
  note = 'This is the first time this customer has written to us. There is no earlier conversation.';
} else if (!lastSeen) {
  note = 'This customer has written to us before and the earlier messages are in your memory, but we do not know exactly when. Do not assume an old request is still in progress: briefly confirm before continuing it.';
} else {
  const hrs  = (Date.now() - lastSeen.getTime()) / 3.6e6;
  const ago  = hrs < 48 ? Math.max(1, Math.round(hrs)) + ' hours' : Math.round(hrs / 24) + ' days';
  const when = new Intl.DateTimeFormat('en-GB', { timeZone: tz, weekday: 'long', day: 'numeric',
                 month: 'long', hour: '2-digit', minute: '2-digit', hour12: false }).format(lastSeen);
  if (hrs < 12) {
    note = '';                                 // same conversation: carry on normally
  } else if (hrs < 24 * 7) {
    note = 'RETURNING CUSTOMER: they last wrote to us ' + ago + ' ago (' + when + '). The earlier conversation is in your memory. '
         + 'Pick up where it left off and refer to it naturally, for example "Welcome back! About the double room you asked about...". '
         + 'Before completing anything from that earlier request, briefly confirm it is still what they want. Do not ask again for details they already gave.';
  } else {
    note = 'RETURNING CUSTOMER AFTER A LONG GAP: they last wrote to us ' + ago + ' ago (' + when + '). '
         + 'Treat the earlier conversation in your memory as background only; that request is probably no longer current. '
         + 'Greet them as a returning customer and do not continue an old booking or quote without first confirming it is still wanted. '
         + 'Prices and availability may have changed since then, so check again with your tools.';
  }
  if (note && lastByStaff) note += ' The last message in that conversation was written personally by our staff: honour what they said.';
}

return [{ json: Object.assign({}, base, {
  isReturning: prior > 0,
  lastSeen: row.last_seen || null,
  continuityNote: note,
}) }];
